function renderCatalogProjectFilters(){selectedCatalogProjectIds=new Set([...selectedCatalogProjectIds].filter(id=>projects.some(project=>sameId(project.id,id))));els.projectSelect.innerHTML=projects.map(project=>`<label><input type="checkbox" data-catalog-project="${esc(project.id)}" ${selectedCatalogProjectIds.has(String(project.id))?"checked":""}><span>${esc(project.name)}</span><small>${project.films.length}</small></label>`).join("");const allLabel=interfaceLanguage()==="en"?"All projects":"Alle Projekte";els.projectHeading.textContent=selectedCatalogProjectIds.size===0?allLabel:selectedCatalogProjectIds.size===1?projects.find(project=>selectedCatalogProjectIds.has(String(project.id)))?.name||allLabel:`${selectedCatalogProjectIds.size} ${interfaceLanguage()==="en"?"projects":"Projekte"}`}
