function selectedMediaType(){return document.querySelector('input[name="filmMediaType"]:checked')?.value==="tv"?"tv":"movie"}
function normalizedFilmIdentifier(value){return String(value??"").trim().toLocaleLowerCase("en-US")}
function filmsShareIdentifier(first,second){return FILM_IDENTIFIER_KEYS.some(key=>{const a=normalizedFilmIdentifier(first?.[key]),b=normalizedFilmIdentifier(second?.[key]);return Boolean(a&&b&&a===b&&(key!=="tmdbId"||filmMediaType(first)===filmMediaType(second)))})}
function redirectPlaylistFilmReferences(oldIds,newId){const oldSet=new Set(oldIds.map(String).filter(id=>id!==String(newId)));if(!oldSet.size)return;playlists.forEach(playlist=>{playlist.filmIds=[...new Set((playlist.filmIds||[]).map(id=>oldSet.has(String(id))?newId:id))];const assignments=new Map();(playlist.filmAssignments||[]).forEach(entry=>{const filmId=oldSet.has(String(entry.filmId))?newId:entry.filmId,key=String(filmId),previous=assignments.get(key)||{};assignments.set(key,{...previous,...entry,filmId,collectionNumber:previous.collectionNumber||entry.collectionNumber||"",details:previous.details||entry.details||""})});playlist.filmAssignments=[...assignments.values()];(playlist.placeholders||[]).forEach(entry=>{if(oldSet.has(String(entry.filmId)))entry.filmId=newId})})}
function mergeFilmIntoProject(target,film){target.films=Array.isArray(target.films)?target.films:[];const hasId=FILM_IDENTIFIER_KEYS.some(key=>normalizedFilmIdentifier(film[key]));if(!hasId){target.films.unshift(film);return film}const matches=target.films.filter(candidate=>filmsShareIdentifier(film,candidate));if(!matches.length){target.films.unshift(film);return film}const base=matches[0],mergedIds=[film.id,...matches.map(match=>match.id)];const copiesByLink=new Map();[...filmCopies(base),...matches.slice(1).flatMap(filmCopies),...filmCopies(film)].forEach(copy=>{const link=String(copy.link||"").trim(),key=link||`missing-${copiesByLink.size}`;if(!copiesByLink.has(key))copiesByLink.set(key,{...copy})});base.copies=[...copiesByLink.values()];base.localizedMetadata=Object.assign({},...matches.map(match=>match.localizedMetadata||{}),film.localizedMetadata||{});FILM_IDENTIFIER_KEYS.forEach(key=>{if(!normalizedFilmIdentifier(base[key]))base[key]=matches.map(match=>match[key]).find(value=>normalizedFilmIdentifier(value))||film[key]||""});const protectedFields=new Set(["id","copies","link","status","localizedMetadata","mediaType",...FILM_IDENTIFIER_KEYS]);[...matches.slice(1),film].forEach(incoming=>Object.keys(base).forEach(key=>{if(!protectedFields.has(key)&&base[key]&&incoming[key]&&String(base[key])!==String(incoming[key]))base[key]=""}));target.films=target.films.filter(candidate=>candidate===base||!matches.includes(candidate));redirectPlaylistFilmReferences(mergedIds,base.id);return base}
