function globalWorkFor(film){return projects.flatMap(project=>project.films||[]).find(candidate=>candidate!==film&&(sameId(candidate.id,film.id)||filmsShareIdentifier(candidate,film)))||null}
function synchronizeWorkMetadata(source){const matching=projects.flatMap(project=>project.films||[]).filter(candidate=>sameId(candidate.id,source.id)||filmsShareIdentifier(candidate,source));matching.forEach(candidate=>{const local={copies:candidate.copies,link:candidate.link,status:candidate.status};copyWorkMetadata(candidate,source);Object.assign(candidate,local)});return source}
function filmIdentityKeys(film){const keys=[`id:${String(film.id)}`];FILM_IDENTIFIER_KEYS.forEach(key=>{const value=normalizedFilmIdentifier(film?.[key]);if(value)keys.push(`${key}:${key==="tmdbId"?`${filmMediaType(film)}:`:""}${value}`)});return keys}
function reconcileDuplicateFilmsGlobally(){const identityIndex=new Map(),canonicalById=new Map(),redirects=new Map();let merged=0;projects.forEach(project=>{const unique=[],projectIndex=new Map();(project.films||[]).forEach(film=>{const keys=filmIdentityKeys(film),canonical=keys.map(key=>identityIndex.get(key)).find(Boolean)||film,oldId=String(film.id);if(canonical!==film){FILM_IDENTIFIER_KEYS.forEach(key=>{if(!normalizedFilmIdentifier(canonical[key])&&normalizedFilmIdentifier(film[key]))canonical[key]=film[key]});canonical.localizedMetadata={...(film.localizedMetadata||{}),...(canonical.localizedMetadata||{})};Object.entries(film).forEach(([key,value])=>{if(!PROJECT_FILM_FIELDS.has(key)&&(canonical[key]===undefined||canonical[key]===null||canonical[key]==="")&&value!==undefined&&value!==null&&value!=="")canonical[key]=structuredClone(value)})}film.id=canonical.id;if(oldId!==String(canonical.id)){redirects.set(oldId,String(canonical.id));merged++}const existing=projectIndex.get(String(canonical.id));if(existing){const copies=new Map();[...filmCopies(existing),...filmCopies(film)].forEach((copy,index)=>{const key=String(copy.link||copy.id||index);if(!copies.has(key))copies.set(key,copy)});existing.copies=[...copies.values()];existing.link=existing.copies[0]?.link||existing.link||film.link||"";existing.status=existing.copies[0]?.status||existing.status||film.status||"";merged++}else{projectIndex.set(String(canonical.id),film);unique.push(film)}canonicalById.set(String(canonical.id),canonical);[...keys,...filmIdentityKeys(canonical)].forEach(key=>identityIndex.set(key,canonical))});project.films=unique});projects.forEach(project=>(project.films||[]).forEach(film=>{const canonical=canonicalById.get(String(film.id));if(!canonical)return;const local={copies:film.copies,link:film.link,status:film.status};copyWorkMetadata(film,canonical);Object.assign(film,local)}));redirects.forEach((newId,oldId)=>redirectPlaylistFilmReferences([oldId],newId));return merged}
function dropFilmOnProject(event){const row=projectDropRow(event.target),targetId=row?.querySelector("[data-project-id]")?.dataset.projectId,reference=draggedFilmReference;event.preventDefault();clearFilmDropState();draggedFilmReference=null;if(!reference||!targetId||sameId(targetId,reference.projectId))return;const source=projects.find(project=>sameId(project.id,reference.projectId)),target=projects.find(project=>sameId(project.id,targetId)),filmIndex=source?.films.findIndex(film=>sameId(film.id,reference.filmId))??-1;if(!source||!target||filmIndex<0)return;const [film]=source.films.splice(filmIndex,1),merged=mergeFilmIntoProject(target,film);save();render();toast(merged.id===film.id?`„${film.title}“ nach „${target.name}“ verschoben`:`„${film.title}“ verschoben und mit dem vorhandenen Eintrag zusammengeführt`)}
function setView(view){if(view===currentView)return;if(currentView==="cinema"){catalogSearchQuery=els.searchInput.value;saveCatalogState()}else archiveSearchQuery=els.searchInput.value;currentView=view;document.documentElement.dataset.view=view;els.cinemaView.hidden=view!=="cinema";els.machineView.hidden=view!=="machine";document.querySelectorAll("[data-view]").forEach(b=>b.classList.toggle("is-active",b.dataset.view===view));if(view==="machine"){const queryChanged=archiveSearchQuery!=="";archiveSearchQuery="";els.searchInput.value="";els.searchInput.blur();setCatalogDrawer(false);if(!archiveHasRendered||queryChanged){els.machineView.classList.add("is-view-loading");els.machineView.setAttribute("aria-busy","true");requestAnimationFrame(()=>setTimeout(()=>{if(currentView==="machine")renderTable()},0))}}else{els.searchInput.value=catalogSearchQuery;if(!catalogHasRendered){els.cinemaView.classList.add("is-view-loading");els.cinemaView.setAttribute("aria-busy","true");requestAnimationFrame(()=>setTimeout(()=>{if(currentView==="cinema")renderCatalog()},0))}}syncNeonHeader()}
function persistActiveProjectSelection(){localStorage.setItem(ACTIVE_KEY,activeProjectId);window.NeonVStorage?.setSetting?.("activeProjectId",activeProjectId).catch(error=>console.warn("Active project setting could not be stored",error))}
function renderSelectedProject(){const project=activeProject();els.projectList.querySelectorAll(".project-row").forEach(row=>{const selected=sameId(row.dataset.projectDrag,project.id);row.classList.toggle("is-active",selected);row.querySelector("[data-project-id]")?.toggleAttribute("aria-current",selected)});els.machineProjectTitle.textContent=project.name;els.projectSummary.textContent=`${project.films.length} ${project.films.length===1?"Film":"Filme"} · ${project.description||"Ohne Beschreibung"}`;if(archiveScrollHost)archiveScrollHost.scrollTop=0;renderTable()}
function selectProject(id){if(currentView==="cinema"){if(id!=="all"&&!projects.some(p=>p.id===id))return;catalogProjectId=id;activeGenre="all";saveCatalogState();scheduleCatalogRefresh({filters:true,menu:true});return}if(!projects.some(p=>p.id===id))return;activeProjectId=id;archiveSearchQuery="";els.searchInput.value="";persistActiveProjectSelection();renderSelectedProject()}
function normalizeRuntime(value){if(value===""||value===null||value===undefined)return "";if(typeof value==="number"||/^\d+(?:\.\d+)?$/.test(String(value).trim())){const seconds=Math.round(Number(value)*60);const hours=Math.floor(seconds/3600);const minutes=Math.floor(seconds%3600/60);return `${hours}:${String(minutes).padStart(2,"0")}:${String(seconds%60).padStart(2,"0")}`}const match=String(value).trim().match(/^(\d{1,3}):([0-5]\d):([0-5]\d)$/);return match?`${Number(match[1])}:${match[2]}:${match[3]}`:""}
function closeProjectRowMenus(){document.querySelectorAll("[data-project-row-popup],[data-playlist-row-popup]").forEach(menu=>{menu.hidden=true;menu.classList.remove("opens-upward")});document.querySelectorAll("[data-project-row-menu],[data-playlist-row-menu]").forEach(button=>button.setAttribute("aria-expanded","false"))}
function toggleProjectRowMenu(id){const menu=document.querySelector(`[data-project-row-popup="${CSS.escape(id)}"]`);const button=document.querySelector(`[data-project-row-menu="${CSS.escape(id)}"]`);if(!menu||!button)return;const willOpen=menu.hidden;closeProjectRowMenus();menu.hidden=!willOpen;if(willOpen&&menu.getBoundingClientRect().bottom>innerHeight-12)menu.classList.add("opens-upward");button.setAttribute("aria-expanded",String(willOpen))}
function togglePlaylistRowMenu(id){const menu=document.querySelector(`[data-playlist-row-popup="${CSS.escape(id)}"]`);const button=document.querySelector(`[data-playlist-row-menu="${CSS.escape(id)}"]`);if(!menu||!button)return;const willOpen=menu.hidden;closeProjectRowMenus();menu.hidden=!willOpen;button.setAttribute("aria-expanded",String(willOpen))}
function editProjectField(id,field,label){const p=projects.find(x=>sameId(x.id,id));if(!p)return;const value=window.prompt(label,p[field]||"");if(value===null)return;p[field]=value.trim();save();render();toast("Projekt aktualisiert")}function deleteProject(id,holdComplete=document.querySelector(`[data-delete-project="${CSS.escape(String(id))}"]`)?.style.getPropertyValue("--hold-progress")==="100%"){if(!holdComplete)return;const project=projects.find(item=>item.id===id);if(!project)return;if(projects.length===1){toast("Das letzte Projekt kann nicht gelöscht werden");return}projects=projects.filter(item=>item.id!==id);if(activeProjectId===id)activeProjectId=projects[0].id;if(catalogProjectId===id){catalogProjectId="all";activeGenre="all";saveCatalogState()}save();render();toast("Projekt gelöscht")}
const deleteProjectWithCatalogCleanup=deleteProject;
deleteProject=function(id,...args){const existed=projects.some(project=>sameId(project.id,id)),result=deleteProjectWithCatalogCleanup(id,...args);if(existed&&!projects.some(project=>sameId(project.id,id))){selectedCatalogProjectIds.delete(String(id));saveCatalogState()}return result};
