function setFilmTab(tab){const active=["general","episodes","copies","playlists"].includes(tab)?tab:"general";document.querySelectorAll("[data-film-tab]").forEach(button=>{const selected=button.dataset.filmTab===active;button.classList.toggle("is-active",selected);button.setAttribute("aria-selected",String(selected))});$("filmGeneralPanel").hidden=active!=="general";$("seriesEpisodesPanel").hidden=active!=="episodes";$("filmCopiesPanel").hidden=active!=="copies";$("filmPlaylistsPanel").hidden=active!=="playlists";if(active==="episodes")renderSeriesEpisodes()}
function updateFilmPlaylistCount(){const checked=[$("filmPlaylistChecklist")].flatMap(root=>[...root.querySelectorAll('[data-playlist-check]:checked')]);$("filmPlaylistCount").textContent=checked.length}
