function readCopyEditor(){editingCopies=[...$("filmCopiesList").querySelectorAll("[data-copy-id]")].map(row=>({id:row.dataset.copyId,title:row.querySelector('[data-copy-field="title"]').value.trim(),storageType:row.querySelector('[data-copy-field="storageType"]').value,link:row.querySelector('[data-copy-field="link"]').value.trim(),access:row.querySelector('[data-copy-field="access"]').value,password:row.querySelector('[data-copy-field="password"]').value,medium:row.querySelector('[data-copy-field="medium"]').value,edition:row.querySelector('[data-copy-field="edition"]').value.trim(),regionCode:row.querySelector('[data-copy-field="regionCode"]').value.trim(),location:row.querySelector('[data-copy-field="location"]').value.trim(),condition:row.querySelector('[data-copy-field="condition"]').value,languages:semanticLanguages(row.querySelector('[data-copy-field="languages"]').value),subtitles:semanticLanguages(row.querySelector('[data-copy-field="subtitles"]').value),resolution:row.querySelector('[data-copy-field="resolution"]').value,quality:row.querySelector('[data-copy-field="quality"]').value,status:row.querySelector('[data-copy-field="status"]').value}))}
