  $("filmCopiesList").querySelectorAll('[data-copy-field="access"]').forEach(select=>select.addEventListener("change",()=>{const row=select.closest(".film-copy"),physical=row.querySelector('[data-copy-field="storageType"]').value==="physical";row.querySelector(".copy-password-field").hidden=physical||select.value!=="password"}));
