function addFilmCopy(){readCopyEditor();editingCopies.push({id:uid("copy"),title:`Fassung ${editingCopies.length+1}`,storageType:"digital",link:"",access:"private",password:"",medium:"",edition:"",regionCode:"",location:"",condition:"",languages:"",subtitles:"",resolution:"",quality:"",status:"prüfen"});renderCopyEditor();setFilmTab("copies")}
let editingSeriesStructure=[],activeSeriesSeason=1,editingEpisodeCopies=[];
function normalizedSeriesStructure(film={}){const stored=Array.isArray(film.seasonsData)?structuredClone(film.seasonsData):[],seasonCount=Math.max(0,Number(film.seasons)||stored.length||0);return Array.from({length:seasonCount},(_,index)=>{const number=index+1,saved=stored.find(season=>Number(season.number)===number)||{},episodes=Array.isArray(saved.episodes)?saved.episodes:[],fallback=seasonCount===1?Number(film.episodes)||0:0,episodeCount=Math.max(0,Number(saved.episodeCount)||episodes.length||fallback);return{number,episodeCount,episodes:Array.from({length:episodeCount},(__,episodeIndex)=>({...episodes[episodeIndex],number:episodeIndex+1,copies:Array.isArray(episodes[episodeIndex]?.copies)?episodes[episodeIndex].copies:[]}))}})}
function syncSeriesStructureFromPlan(){if(selectedMediaType()!=="tv")return;const seasonCount=Math.max(0,Number($("filmSeasons").value)||0);editingSeriesStructure=Array.from({length:seasonCount},(_,index)=>{const number=index+1,existing=editingSeriesStructure.find(season=>Number(season.number)===number)||{number,episodeCount:0,episodes:[]},input=$("seriesSeasonPlan").querySelector(`[data-season-episode-count="${number}"]`),episodeCount=Math.max(0,Number(input?.value??existing.episodeCount)||0);return{...existing,number,episodeCount,episodes:Array.from({length:episodeCount},(__,episodeIndex)=>({...existing.episodes?.[episodeIndex],number:episodeIndex+1,copies:Array.isArray(existing.episodes?.[episodeIndex]?.copies)?existing.episodes[episodeIndex].copies:[]}))}});$("filmEpisodes").value=editingSeriesStructure.reduce((sum,season)=>sum+season.episodeCount,0);$("seriesEpisodeCount").textContent=$("filmEpisodes").value||"0"}
function renderSeriesSeasonPlan(){if(selectedMediaType()!=="tv"){$("seriesSeasonPlan").innerHTML="";return}const seasonCount=Math.max(0,Number($("filmSeasons").value)||0);while(editingSeriesStructure.length<seasonCount)editingSeriesStructure.push({number:editingSeriesStructure.length+1,episodeCount:0,episodes:[]});$("seriesSeasonPlan").innerHTML=seasonCount?`<div class="series-season-plan-head"><strong>Folgen pro Staffel</strong><small>Diese Angaben erzeugen den Bereich „Einzelfolgen“.</small></div><div class="series-season-counts">${Array.from({length:seasonCount},(_,index)=>{const season=editingSeriesStructure[index]||{};return`<label>Staffel ${index+1}<input type="number" min="0" max="999" data-season-episode-count="${index+1}" value="${Number(season.episodeCount)||0}"></label>`}).join("")}</div>`:"<p class=\"muted\">Trage die Anzahl der Staffeln ein.</p>";$("seriesSeasonPlan").querySelectorAll("[data-season-episode-count]").forEach(input=>input.addEventListener("input",()=>{syncSeriesStructureFromPlan();renderSeriesEpisodes()}));syncSeriesStructureFromPlan()}
