function renderEpisodeCopies(){$("episodeCopiesList").innerHTML=editingEpisodeCopies.map((copy,index)=>`<section class="episode-copy" data-episode-copy="${esc(copy.id)}"><div class="film-copy-head"><strong>Fassung ${index+1}</strong><button type="button" data-remove-episode-copy="${esc(copy.id)}">Entfernen</button></div><div class="form-grid"><label>Bezeichnung<input data-episode-copy-field="title" value="${esc(copy.title||"")}" placeholder="z. B. Originalfassung"></label><label>Art<select data-episode-copy-field="storageType"><option value="digital" ${copy.storageType!=="physical"?"selected":""}>Digital</option><option value="physical" ${copy.storageType==="physical"?"selected":""}>Physisch</option></select></label><label class="span-2">Link / Speicherort<input data-episode-copy-field="link" value="${esc(copy.link||copy.location||"")}" placeholder="https://… oder Regal"></label><label>Sprachen<input data-episode-copy-field="languages" value="${esc(languageText(copy.languages))}"></label><label>Untertitel<input data-episode-copy-field="subtitles" value="${esc(languageText(copy.subtitles))}"></label><label>Status<select data-episode-copy-field="status"><option value="verfügbar" ${copy.status==="verfügbar"?"selected":""}>Verfügbar</option><option value="prüfen" ${copy.status==="prüfen"?"selected":""}>Prüfen</option><option value="nicht verfügbar" ${copy.status==="nicht verfügbar"?"selected":""}>Nicht verfügbar</option></select></label></div></section>`).join("");$("episodeCopiesList").querySelectorAll("[data-remove-episode-copy]").forEach(button=>button.addEventListener("click",()=>{readEpisodeCopies();editingEpisodeCopies=editingEpisodeCopies.filter(copy=>!sameId(copy.id,button.dataset.removeEpisodeCopy));renderEpisodeCopies()}))}
