function youtubeVideoId(value){try{const url=new URL(value),host=url.hostname.toLowerCase().replace(/^www\./,"");if(host==="youtu.be")return url.pathname.slice(1).split("/")[0];if(host==="youtube.com"||host.endsWith(".youtube.com")||host==="youtube-nocookie.com"||host.endsWith(".youtube-nocookie.com")){if(url.pathname.startsWith("/embed/"))return url.pathname.split("/")[2];if(url.pathname.startsWith("/shorts/"))return url.pathname.split("/")[2];return url.searchParams.get("v")||""}}catch{}return ""}
