function archiveVideoScore(file){const name=String(file.name||"").toLowerCase(),format=String(file.format||"").toLowerCase();if(!/\.(mp4|m4v|webm|ogv|ogg)$/.test(name)||/(_thumb|sample|trailer|preview)\b/.test(name))return-1;let score=0;if(/\.mp4$/.test(name))score+=60;if(/h\.264|mpeg4|512kb/.test(format))score+=35;if(String(file.source||"").toLowerCase()==="original")score+=20;if(/webm/.test(name)||/webm/.test(format))score+=12;return score+Math.min(Number(file.size||0)/100000000,10)}
