async function synchronizeProjectCovers(){if(projectCoverSyncRunning)return;const project=activeProject(),films=projectFilmsWithoutCover(project);if(!films.length){updateProjectSyncButton();return}if(!tmdbToken){toast(interfaceLanguage()==="de"?"Bitte zuerst den TMDB-Token hinterlegen":"Please add your TMDB token first");openApiConfig("tmdb");return}projectCoverSyncRunning=true;let completed=0,added=0,failed=0;const requested=selectedFilmLocale(),locale=requested==="original"?(interfaceLanguage()==="de"?"de-DE":"en-US"):requested;setProjectSyncButton({state:"progress",completed,total:films.length});try{for(const film of films){try{await synchronizeProjectFilm(film,locale);await persistSynchronizedFilm(project,film);added++}catch(error){console.warn("Cover synchronization skipped",film.title,error);failed++}completed++;setProjectSyncButton({state:"progress",completed,total:films.length});if(completed<films.length&&completed%TMDB_SYNC_CHUNK_SIZE===0)await wait(TMDB_SYNC_CHUNK_PAUSE_MS)}renderSelectedProject();setProjectSyncButton({state:"complete",completed,total:films.length,added,failed});toast(interfaceLanguage()==="de"?`${added} Cover ergänzt${failed?`, ${failed} ohne Treffer`:""}`:`${added} covers added${failed?`, ${failed} without a match`:""}`);setTimeout(()=>{if(!projectCoverSyncRunning&&sameId(activeProjectId,project.id))updateProjectSyncButton()},2400)}catch(error){console.error("Project cover synchronization failed",error);setProjectSyncButton({state:"error"});toast(interfaceLanguage()==="de"?"Die Synchronisierung konnte nicht fortgesetzt werden. Bitte Konsole und Speicherzugriff prüfen.":"Synchronization could not continue. Please check the console and storage access.")}finally{projectCoverSyncRunning=false}}
