function renderTmdbResults(results){tmdbSearchResults=results;const mediaType=selectedMediaType();$("tmdbResults").hidden=!results.length;$("tmdbResults").innerHTML=results.map((item,index)=>{const title=mediaType==="tv"?item.name:item.title,originalTitle=mediaType==="tv"?item.original_name:item.original_title,year=String(mediaType==="tv"?item.first_air_date:item.release_date).slice(0,4)||"—",poster=item.poster_path?`<img src="${TMDB_IMAGE_BASE_URL}/w92${esc(item.poster_path)}" alt="">`:`<span class="tmdb-result-placeholder" aria-hidden="true"></span>`;return `<button type="button" class="tmdb-result" data-tmdb-result="${index}">${poster}<span><strong>${esc(title||"")}</strong><small>${esc(year)}${originalTitle&&originalTitle!==title?` · ${esc(originalTitle)}`:""}</small><em>${esc(item.overview||"Keine Beschreibung verfügbar.")}</em></span><b>Daten übernehmen</b></button>`}).join("");$("tmdbResults").querySelectorAll("[data-tmdb-result]").forEach(button=>button.addEventListener("click",async()=>{await applyTmdbResult(tmdbSearchResults[Number(button.dataset.tmdbResult)]);updateIdentifierStatuses()}))}
