let projectMergeInProgress=false;
const nextPaint=()=>new Promise(resolve=>requestAnimationFrame(()=>resolve()));
function setProjectMergeIndicator(row,{state="progress",completed=0,total=0,label=""}={}){
  const control=row?.querySelector("[data-project-merge-status]"),text=control?.querySelector(".sync-project-label"),count=control?.querySelector(".sync-project-count");
  if(!row||!control||!text||!count)return;
  const english=interfaceLanguage()==="en",progress=state==="complete"?100:(total?Math.round(completed/total*92):0);
  control.hidden=false;control.dataset.state=state;control.style.setProperty("--sync-progress",`${progress}%`);control.toggleAttribute("aria-busy",state==="progress");
  if(state==="complete"){text.textContent=english?"Done":"Fertig";count.textContent="";control.setAttribute("aria-label",english?"Projects merged":"Projekte zusammengeführt");return}
  if(state==="error"){text.textContent=english?"Merge failed":"Zusammenführen fehlgeschlagen";count.textContent="";control.setAttribute("aria-label",text.textContent);return}
  text.textContent=label||(total?`${completed} / ${total}`:(english?"Preparing …":"Wird vorbereitet …"));count.textContent="";control.setAttribute("aria-label",label||(english?`Merging projects: ${completed} of ${total}`:`Projekte werden zusammengeführt: ${completed} von ${total}`));
}
async function mergeProjectsWithProgress(sourceId,targetId){
  if(projectMergeInProgress)return;
  const source=projects.find(project=>sameId(project.id,sourceId)),dest=projects.find(project=>sameId(project.id,targetId));
  if(!source||!dest)return;
  const snapshot={projects:structuredClone(projects),playlists:structuredClone(playlists),activeProjectId},row=els.projectList.querySelector(`[data-project-drag="${CSS.escape(String(targetId))}"]`),films=[...(source.films||[])],total=Math.max(films.length,1),started=performance.now();
  let committed=false;
  projectMergeInProgress=true;
  if(row){row.classList.add("is-project-merging");row.setAttribute("aria-busy","true");setProjectMergeIndicator(row,{completed:0,total:films.length})}els.projectList.classList.add("has-project-merge");toast(`„${source.name}“ wird mit „${dest.name}“ zusammengeführt …`);await nextPaint();
  try{
    for(let index=0;index<films.length;index++){
      mergeFilmIntoProject(dest,films[index]);
      const completed=index+1;
      if(completed%20===0||completed===films.length){if(row)setProjectMergeIndicator(row,{completed,total:films.length});await nextPaint()}
    }
    projects=projects.filter(project=>!sameId(project.id,sourceId));
    if(sameId(activeProjectId,sourceId))activeProjectId=targetId;
    if(row){const control=row.querySelector("[data-project-merge-status]");setProjectMergeIndicator(row,{completed:total,total,label:interfaceLanguage()==="en"?"Saving …":"Speichern …"});control?.setAttribute("aria-label",interfaceLanguage()==="en"?"Projects are being saved securely":"Projekte werden sicher gespeichert");control?.style.setProperty("--sync-progress","96%")}await nextPaint();
    if(!window.NeonVStorage?.mergeProjects)throw new Error("indexeddb-merge-unavailable");
    stateRevision=Date.now();
    await window.NeonVStorage.mergeProjects({sourceId,targetProject:dest,playlists,activeProjectId,stateRevision});
    committed=true;
    writeLocalSnapshot();
    render();
    const completedRow=els.projectList.querySelector(`[data-project-drag="${CSS.escape(String(targetId))}"]`);
    if(completedRow){completedRow.classList.add("is-project-merging","is-project-drop-complete");completedRow.setAttribute("aria-busy","false");setProjectMergeIndicator(completedRow,{state:"complete",completed:total,total});if(performance.now()-started<380)await new Promise(resolve=>setTimeout(resolve,380-(performance.now()-started)));setTimeout(()=>{const control=completedRow.querySelector("[data-project-merge-status]");completedRow.classList.remove("is-project-merging","is-project-drop-complete");completedRow.removeAttribute("aria-busy");if(control){control.hidden=true;control.removeAttribute("aria-busy");control.style.removeProperty("--sync-progress")}},900)}
    toast("Projekte sicher zusammengelegt und identische Einträge synchronisiert")
  }catch(error){
    console.error("Project merge failed",error);if(row){setProjectMergeIndicator(row,{state:"error"});row.setAttribute("aria-busy","false")}if(!committed){await new Promise(resolve=>setTimeout(resolve,650));projects=snapshot.projects;playlists=snapshot.playlists;activeProjectId=snapshot.activeProjectId;render();toast("Die Zusammenführung wurde zurückgerollt – beide Projekte sind unverändert erhalten")}else{try{render()}catch{}toast("Die Projekte wurden gespeichert; die Ansicht konnte nicht vollständig aktualisiert werden")}
  }finally{projectMergeInProgress=false;els.projectList.classList.remove("has-project-merge")}
}
