function registerWebMCP(){const ctx=document.modelContext;if(!ctx?.registerTool)return;const add=(tool)=>Promise.resolve(ctx.registerTool(tool)).catch(()=>{});add({name:"list_videothek_projects",title:"Videothek-Projekte auflisten",description:"Listet die vorhandenen Videothek-Projekte und ihre Filmzahlen auf.",inputSchema:{type:"object",properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>projects.map(p=>({id:p.id,name:p.name,filmCount:p.films.length}))});add({name:"create_videothek_project",title:"Videothek-Projekt anlegen",description:"Legt ein neues leeres Videothek-Projekt an und macht es zum aktiven Projekt.",inputSchema:{type:"object",properties:{name:{type:"string",minLength:1},description:{type:"string"}},required:["name"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:({name,description=""})=>{if(typeof name!=="string"||!name.trim())throw new Error("Ein Projektname ist erforderlich.");const p={id:uid("projekt"),name:name.trim(),description:String(description),createdAt:new Date().toISOString(),films:[]};projects.push(p);activeProjectId=p.id;save();render();return{id:p.id,name:p.name}}});add({name:"add_film_reference",title:"Filmverweis hinzufügen",description:"Fügt dem aktiven Projekt einen Film mit Metadaten und externem Speicherlink hinzu. Es wird keine Filmdatei gespeichert.",inputSchema:{type:"object",properties:{title:{type:"string",minLength:1},link:{type:"string"},year:{type:"integer"},genre:{type:"string"},description:{type:"string"}},required:["title","link"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:(input)=>{if(typeof input.title!=="string"||!input.title.trim()||typeof input.link!=="string")throw new Error("Titel und Link sind erforderlich.");const f={id:uid("film"),title:input.title.trim(),link:input.link.trim(),year:input.year||"",genre:input.genre||"",description:input.description||"",runtime:"",director:"",cover:"",trailer:"",status:"prüfen",rating:""};activeProject().films.unshift(f);save();render();return{id:f.id,projectId:activeProjectId}}})}
