$("smartImportButton").addEventListener("click",()=>$("smartImportDialog").showModal());
$("copySmartImportButton").addEventListener("click",async()=>{await navigator.clipboard.writeText(smartImportPrompt);$("smartImportStatus").textContent="Kopiert."});
$("smartImportNextButton").addEventListener("click",()=>{$("smartImportDialog").close();$("importInput").click()});
$("syncProjectButton").addEventListener("click",synchronizeProjectCovers);
function migrateSeriesStructures(){let changed=false;projects.forEach(project=>(project.films||[]).forEach(film=>{if(filmMediaType(film)!=="tv"||Array.isArray(film.seasonsData))return;film.seasonsData=normalizedSeriesStructure(film);changed=true}));return changed}
async function initializeApplication(){
  document.documentElement.dataset.view=currentView;
  initializeTheme();
  initializeTmdbToken();
  if(window.NeonVStorage)try{
    const stored=await window.NeonVStorage.initialize({projects,playlists,settings:indexedStorageSettings()});
    const localRevision=stateRevision,indexedRevision=Number(stored.settings?.stateRevision)||0,localStateIsNewer=localSnapshotIsComplete()&&localRevision>indexedRevision;
    if(String(stored.source).startsWith("indexedDB")&&!localStateIsNewer){
      projects=stored.projects.length?stored.projects:projects;
      playlists=stored.playlists.length?stored.playlists:playlists;
      stateRevision=indexedRevision;
      projects.forEach(project=>(project.films||[]).forEach(film=>{if(!film.globalWorkId&&film.catalogWorkId)film.globalWorkId=film.catalogWorkId;delete film.catalogWorkId}));
      activeProjectId=projects.some(project=>sameId(project.id,stored.settings?.activeProjectId))?String(stored.settings.activeProjectId):projects[0]?.id||activeProjectId;
      activePlaylistId=playlists.some(playlist=>sameId(playlist.id,stored.settings?.activePlaylistId))?String(stored.settings.activePlaylistId):playlists[0]?.id||activePlaylistId;
    }
  }catch(error){console.warn("Neon V IndexedDB initialization failed; localStorage remains active",error)}
  const normalizedListKinds=normalizeListKinds(),migratedSeriesStructures=migrateSeriesStructures();
  if(migratedSeriesStructures){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(projects))}catch{}persistIndexedState()}
  registerWebMCP();
  els.searchInput.value=catalogSearchQuery;
  render(false);
  setArchiveSection(activeArchiveSection);
  translateUi();
  if(document.documentElement.lang==="en")new MutationObserver(records=>records.forEach(record=>record.addedNodes.forEach(node=>{if(node.nodeType===Node.ELEMENT_NODE)translateUi(node)}))).observe(document.body,{childList:true,subtree:true});
  delete document.documentElement.dataset.storageLoading;
  els.cinemaView.classList.add("is-view-loading");
  els.cinemaView.setAttribute("aria-busy","true");
  requestAnimationFrame(()=>setTimeout(renderCatalog,0));
  const maintainCatalog=()=>{const reconciledFilmDuplicates=reconcileDuplicateFilmsGlobally(),reconciledPlaylists=reconcileAllPlaylistPlaceholders();syncPlaylistCollectionNumbers();if(normalizedListKinds||reconciledFilmDuplicates||reconciledPlaylists){try{localStorage.setItem(PLAYLISTS_KEY,JSON.stringify(playlists));if(reconciledFilmDuplicates)localStorage.setItem(STORAGE_KEY,JSON.stringify(projects))}catch{}persistIndexedState();render()}if(reconciledFilmDuplicates)toast(reconciledFilmDuplicates===1?"Eine Dublette anhand übereinstimmender IDs zusammengeführt":`${reconciledFilmDuplicates} Dubletten anhand übereinstimmender IDs zusammengeführt`)};
  const maintenanceKey="videothek-catalog-maintenance-v1",maintenanceVersion="2026-09-20-1";
  if(localStorage.getItem(maintenanceKey)!==maintenanceVersion){const runMaintenance=()=>{maintainCatalog();localStorage.setItem(maintenanceKey,maintenanceVersion)};if("requestIdleCallback" in window)requestIdleCallback(runMaintenance,{timeout:10000});else setTimeout(runMaintenance,4000)}
}
initializeApplication();






































